using System;
using System.Collections.Generic;
using System.IO;
using UnityEngine;

namespace Homesteader.Modding
{
    /// <summary>
    /// Binds a modded asset's `models[].file` reference to an actual GameObject.
    ///
    /// ORDER OF RESOLUTION (first hit wins):
    ///   1. An explicit prefab path in the manifest ("prefab": "...").
    ///   2. A prefab generated by the Editor pipeline
    ///      (Tools > Homesteader > Generate Mod Prefabs), found by convention at
    ///      &lt;modsRoot&gt;/&lt;mod_id&gt;/prefabs/&lt;modelname&gt;.prefab.
    ///   3. A runtime-parsed OBJ, for mods that ship plain .obj geometry.
    ///
    /// WHY PREFABS: Unity converts FBX into a mesh at import time, and that
    /// conversion is NOT available at runtime in a built player. So an FBX can
    /// only reach the game as an already-imported prefab (or AssetBundle /
    /// Addressables entry). The Editor-side prefab generator covers that; the OBJ
    /// parser covers mods that cannot run a Unity build step.
    ///
    /// The prefab itself is loaded through the provider injected at construction
    /// time, so this class stays free of any direct Addressables/Resources
    /// dependency and can be unit-tested.
    /// </summary>
    public sealed class FileAssetResolver : IModAssetResolver
    {
        /// <summary>Looks up a prefab by a project-relative path/key.</summary>
        public interface IPrefabProvider
        {
            GameObject LoadPrefab(string key);
        }

        private readonly IPrefabProvider provider;
        private readonly string modsRoot;
        private readonly Action<string> log;

        private readonly Dictionary<string, GameObject> cache =
            new Dictionary<string, GameObject>(StringComparer.OrdinalIgnoreCase);

        public FileAssetResolver(IPrefabProvider provider, string modsRoot, Action<string> log = null)
        {
            this.provider = provider;
            this.modsRoot = modsRoot;
            this.log = log;
        }

        public bool TryResolvePrefab(ModInfo mod, ModJsonValue assetManifest, out GameObject prefab)
        {
            prefab = null;
            if (assetManifest == null) return false;

            string assetId = assetManifest.Get("id").AsString();
            if (string.IsNullOrEmpty(assetId)) return false;

            // Cache on the NAMESPACE-QUALIFIED id. Two mods may legitimately ship
            // an asset with the same id ("tree_oak"); keying on the bare id would
            // hand the second mod the first mod's prefab.
            string cacheKey = Qualify(mod, assetManifest, assetId);

            // Cached (including negative results), so a missing model is not
            // re-probed for every one of hundreds of spawn attempts.
            if (cache.TryGetValue(cacheKey, out GameObject cached))
            {
                prefab = cached;
                return prefab != null;
            }

            prefab = Resolve(mod, assetManifest);
            cache[cacheKey] = prefab;
            return prefab != null;
        }

        /// <summary>
        /// Builds the namespace-qualified key for an asset, matching what
        /// ModLoader uses when it registers assets (AssetManifestSummary.ns).
        /// Prefers an explicit qualified_id / namespace in the manifest, then
        /// falls back to the owning mod's id, then to "core".
        /// </summary>
        private static string Qualify(ModInfo mod, ModJsonValue manifest, string assetId)
        {
            string explicitQualified = manifest.Get("qualified_id").AsString();
            if (!string.IsNullOrWhiteSpace(explicitQualified))
                return explicitQualified.Trim();

            string ns = manifest.Get("namespace").AsString();
            if (string.IsNullOrWhiteSpace(ns))
                ns = manifest.Get("ns").AsString();
            if (string.IsNullOrWhiteSpace(ns))
                ns = mod?.Manifest?.Id;
            if (string.IsNullOrWhiteSpace(ns))
                ns = "core";

            return $"{ns.Trim().ToLowerInvariant()}:{assetId}";
        }

        private GameObject Resolve(ModInfo mod, ModJsonValue manifest)
        {
            // 1. Explicit prefab reference.
            string explicitPrefab = manifest.Get("prefab").AsString();
            if (!string.IsNullOrEmpty(explicitPrefab))
            {
                GameObject byPath = LoadPrefabFromMod(mod, explicitPrefab);
                if (byPath != null) return byPath;
            }

            // 2. Generated prefab, matched by the declared model names.
            // A mod may hold many assets, and two assets may even reference the
            // SAME model file (e.g. recoloured variants). Resolution therefore
            // keys on the ASSET ID first - which the prefab generator names
            // prefabs after - and only falls back to the model stem.
            string assetIdForPrefab = manifest.Get("id").AsString();
            if (!string.IsNullOrEmpty(assetIdForPrefab))
            {
                GameObject byAssetId = LoadFromModPrefabs(mod, assetIdForPrefab);
                if (byAssetId != null) return byAssetId;
            }

            // Fallback: the generated prefab named after the model itself. This
            // keeps older mods working, and covers assets whose id and model
            // stem happen to match.
            foreach (string modelName in DeclaredModelNames(manifest))
            {
                string stem = Path.GetFileNameWithoutExtension(modelName);
                if (string.IsNullOrEmpty(stem)) continue;

                GameObject generated = LoadFromModPrefabs(mod, stem);
                if (generated != null) return generated;
            }

            // 3. Runtime OBJ parse (mods that ship .obj and skip the editor step).
            foreach (string modelName in DeclaredModelNames(manifest))
            {
                if (!modelName.EndsWith(".obj", StringComparison.OrdinalIgnoreCase))
                    continue;

                GameObject built = TryBuildFromObj(mod, modelName);
                if (built != null) return built;
            }

            log?.Invoke($"[Mods] No model resolved for '{manifest.Get("id").AsString()}' " +
                        $"in mod '{mod?.Manifest?.Id}'.");
            return null;
        }

        private static IEnumerable<string> DeclaredModelNames(ModJsonValue manifest)
        {
            ModJsonValue models = manifest["models"];
            if (models == null || !models.IsArray)
                yield break;

            foreach (ModJsonValue entry in models.Items)
            {
                // Entries are objects ({"file": "x.fbx"}); tolerate bare strings.
                string file = entry.IsObject ? entry.Get("file").AsString() : entry.AsString();
                if (!string.IsNullOrEmpty(file))
                    yield return file;
            }
        }

        private GameObject LoadPrefabFromMod(ModInfo mod, string relativePath)
        {
            if (mod == null || string.IsNullOrEmpty(mod.RootPath))
                return null;

            // Ask the provider first using the conventional key; this is what an
            // Addressables or AssetBundle implementation would use.
            if (provider != null)
            {
                string key = $"{mod.Manifest?.Id}/{relativePath}";
                GameObject viaProvider = provider.LoadPrefab(key);
                if (viaProvider != null) return viaProvider;
            }

            // Fall back to shipping the prefab inside the mod folder itself.
            string abs = ModFileResolver.ResolveAssetPath(mod, relativePath);
            if (abs != null && abs.EndsWith(".obj", StringComparison.OrdinalIgnoreCase))
                return TryBuildFromObj(mod, relativePath);

            return null;
        }

        private GameObject LoadFromModPrefabs(ModInfo mod, string stem)
        {
            if (mod == null) return null;

            // The Editor generator writes prefabs here, inside the mod folder, so
            // a mod stays self-contained and travels with its geometry.
            string[] candidates =
            {
                $"prefabs/{stem}.prefab",
                $"models/{stem}.prefab",
                $"{stem}.prefab"
            };

            foreach (string rel in candidates)
            {
                if (provider != null)
                {
                    GameObject viaProvider = provider.LoadPrefab($"{mod.Manifest?.Id}/{rel}");
                    if (viaProvider != null) return viaProvider;
                }
            }

            return null;
        }

        private GameObject TryBuildFromObj(ModInfo mod, string modelName)
        {
            string abs = ModFileResolver.ResolveAssetPath(mod, modelName);
            if (abs == null)
            {
                // Also try the conventional models/ subfolder.
                abs = ModFileResolver.ResolveAssetPath(mod, $"models/{Path.GetFileName(modelName)}");
            }
            if (abs == null || !File.Exists(abs)) return null;

            try
            {
                string text = File.ReadAllText(abs);
                ObjMeshParser.ParsedObj parsed = ObjMeshParser.Parse(text);
                if (parsed == null || !parsed.HasGeometry)
                {
                    log?.Invoke($"[Mods] OBJ '{modelName}' contained no geometry.");
                    return null;
                }

                return ObjPrefabBuilder.Build(modelName, parsed, abs);
            }
            catch (Exception ex)
            {
                log?.Invoke($"[Mods] Failed to build OBJ '{modelName}': {ex.Message}");
                return null;
            }
        }
    }
}
